;	Drop stick and go back for it. Generated by tools/build-dropstick.js from NHL Hockey (92) Sprites.anim (same skater frame numbers as NHL 94; no NHL 94 ROM found in roms/).
;	Append to frames94.asm after the last SPA table. SPFnew is the first frame number after the retail player
;	sheet (the new frames are added to Sprites.anim in this order). Timing follows SPAskatewp (10), SPAstop (4)
;	and SPAsweepchk (4/8). Facing numbers are dirtab's: 0 north, clockwise.
;
;	SPFnostick: 8 frames per facing, the retail frame with the stick taken out:
;	  +0 glide (SPFskatewp+5d), +1..+4 stride (SPFskatewp+5d+1..4), +5,+6 stop (SPFstop+2d..), +7 reach (SPFsweep+2d)
;	SPFloosestick: 3 frames per facing d (the facing the stick was dropped in), a separate object drawn at the
;	blade heel and sorted by y with the players: +0 standing on its blade, +1 falling, +2 flat on the ice.
;	The player is then picked up with SPAgetstick in facing d+4, standing where SPFsweep+2(d+4) puts its
;	blade (its hotspot) on the heel. The flat stick lies exactly under that frame's stick.

SPFnostick	=	SPFnew				; 64 frames (stickless skater)
SPFloosestick	=	SPFnostick+64		; 24 frames (dropped stick object)

SPAdropstick	=	*-SPAlist			;stick slips: blade catches, player skates on empty-handed (facing kept)
SPAdropstick_table:
.t								;offset to each direction of animation (0-7)
	dc.w	.0-.t
	dc.w	.1-.t
	dc.w	.2-.t
	dc.w	.3-.t
	dc.w	.4-.t
	dc.w	.5-.t
	dc.w	.6-.t
	dc.w	.7-.t
	dc.w	0

.0	dc.w	SPFskatewp+1,10,SPFnostick+2,6,SPFnostick+3,6,SPFnostick+4,8,SPFnostick+0,-10
.1	dc.w	SPFskatewp+6,10,SPFnostick+10,6,SPFnostick+11,6,SPFnostick+12,8,SPFnostick+8,-10
.2	dc.w	SPFskatewp+11,10,SPFnostick+18,6,SPFnostick+19,6,SPFnostick+20,8,SPFnostick+16,-10
.3	dc.w	SPFskatewp+16,10,SPFnostick+26,6,SPFnostick+27,6,SPFnostick+28,8,SPFnostick+24,-10
.4	dc.w	SPFskatewp+21,10,SPFnostick+34,6,SPFnostick+35,6,SPFnostick+36,8,SPFnostick+32,-10
.5	dc.w	SPFskatewp+26,10,SPFnostick+42,6,SPFnostick+43,6,SPFnostick+44,8,SPFnostick+40,-10
.6	dc.w	SPFskatewp+31,10,SPFnostick+50,6,SPFnostick+51,6,SPFnostick+52,8,SPFnostick+48,-10
.7	dc.w	SPFskatewp+36,10,SPFnostick+58,6,SPFnostick+59,6,SPFnostick+60,8,SPFnostick+56,-10

SPAstickfall	=	*-SPAlist			;the dropped stick object: stands, falls, lies (facing = facing it was dropped in)
SPAstickfall_table:
.t								;offset to each direction of animation (0-7)
	dc.w	.0-.t
	dc.w	.1-.t
	dc.w	.2-.t
	dc.w	.3-.t
	dc.w	.4-.t
	dc.w	.5-.t
	dc.w	.6-.t
	dc.w	.7-.t
	dc.w	0

.0	dc.w	SPFloosestick+0,6,SPFloosestick+1,6,SPFloosestick+2,-8
.1	dc.w	SPFloosestick+3,6,SPFloosestick+4,6,SPFloosestick+5,-8
.2	dc.w	SPFloosestick+6,6,SPFloosestick+7,6,SPFloosestick+8,-8
.3	dc.w	SPFloosestick+9,6,SPFloosestick+10,6,SPFloosestick+11,-8
.4	dc.w	SPFloosestick+12,6,SPFloosestick+13,6,SPFloosestick+14,-8
.5	dc.w	SPFloosestick+15,6,SPFloosestick+16,6,SPFloosestick+17,-8
.6	dc.w	SPFloosestick+18,6,SPFloosestick+19,6,SPFloosestick+20,-8
.7	dc.w	SPFloosestick+21,6,SPFloosestick+22,6,SPFloosestick+23,-8

SPAstopnostick	=	*-SPAlist			;scrape stop without a stick (as SPAstop)
