	dc.w	.7-.t
	dc.w	1

.0	dc.w	SPFnostick+5,4,SPFnostick+6,-4
.1	dc.w	SPFnostick+13,4,SPFnostick+14,-4
.2	dc.w	SPFnostick+21,4,SPFnostick+22,-4
.3	dc.w	SPFnostick+29,4,SPFnostick+30,-4
.4	dc.w	SPFnostick+37,4,SPFnostick+38,-4
.5	dc.w	SPFnostick+45,4,SPFnostick+46,-4
