.4	dc.w	SPFnostick+33,10,SPFnostick+34,10,SPFnostick+35,10,SPFnostick+36,-10
.5	dc.w	SPFnostick+41,10,SPFnostick+42,10,SPFnostick+43,10,SPFnostick+44,-10
.6	dc.w	SPFnostick+49,10,SPFnostick+50,10,SPFnostick+51,10,SPFnostick+52,-10
.7	dc.w	SPFnostick+57,10,SPFnostick+58,10,SPFnostick+59,10,SPFnostick+60,-10

